class Solution:
    def platesBetweenCandles(self, s: str, queries: list[list[int]]) -> list[int]:
        n = len(s)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + (1 if s[i] == '*' else 0)
        left_candle = [-1] * n
        right_candle = [-1] * n
        candle = -1
        for i in range(n):
            if s[i] == '|':
                candle = i
            left_candle[i] = candle
        candle = -1
        for i in range(n - 1, -1, -1):
            if s[i] == '|':
                candle = i
            right_candle[i] = candle
        result = []
        for l, r in queries:
            lc = right_candle[l]
            rc = left_candle[r]
            if lc != -1 and rc != -1 and lc < rc:
                result.append(prefix[rc] - prefix[lc + 1])
            else:
                result.append(0)
        return result

